function mapLegacyTestStatus(status, score) {
  if (status === "Concluído" || status === "Concluido") {
    return score != null ? "Avaliado" : "Concluído";
  }
  if (status === "Enviada") return "Enviado";
  if (status === "Pendente") return "Enviado";
  return status || "Enviado";
}

