let recrutamentoTab = "pipeline";
let selecaoTab = "instrumentos";
let contratacaoFiltro = "pre-admissao";

function parseAppHash(hash = window.location.hash) {
  const raw = String(hash || "").replace(/^#/, "").trim();
  const [path, query = ""] = raw.split("?");
  const parts = path.split("/").filter(Boolean);
  const hub = parts[0] || "";
  const tab = parts[1] || "";
  const params = Object.fromEntries(new URLSearchParams(query));
  return { hub, tab, filtro: params.filtro || "", raw };
}

function hubHash(hub, tab, filtro) {
  let h = tab ? `${hub}/${tab}` : hub;
  if (filtro) h += `?filtro=${encodeURIComponent(filtro)}`;
  return h;
}

/** Resolve legacy + hub hashes into { page, options } for goToPage/showPage */
function resolveAppHash(hash = window.location.hash) {
  const { hub, tab, filtro, raw } = parseAppHash(hash);
  if (!hub) return { page: "dashboard", options: {} };

  if (hub === "recrutamento") {
    const map = { pipeline: "pipeline", pendencias: "pendencias", vagas: "jobs", talentos: "talentos" };
    const page = map[tab] || "pipeline";
    return { page, options: { recrutamentoTab: tab || "pipeline" } };
  }
  if (hub === "selecao") {
    if (tab === "entrevistas") return { page: "entrevistas", options: { selecaoTab: "entrevistas" } };
    if (tab === "resultados") return { page: "resultados", options: { selecaoTab: "resultados" } };
    if (tab === "relatorio" || tab === "relatorios" || tab === "painel") {
      return { page: "painel", options: { selecaoTab: "relatorio" } };
    }
    return { page: "selecao", options: { selecaoTab: "instrumentos" } };
  }
  if (hub === "contratacao") {
    return { page: "contratacao", options: { contratacaoFiltro: filtro || "pre-admissao" } };
  }

  // Legacy single-segment hashes
  if (hub === "pipeline") return { page: "pipeline", options: {} };
  if (hub === "pendencias") return { page: "pendencias", options: {} };
  if (hub === "vagas") return { page: "jobs", options: {} };
  if (hub === "talentos") return { page: "talentos", options: {} };
  if (hub === "entrevistas") return { page: "entrevistas", options: {} };
  if (hub === "selecao") return { page: "selecao", options: { selecaoTab: "instrumentos" } };
  if (hub === "resultados") {
    if (filtro === "pre-admissao" || tab === "preadmissao") {
      return { page: "contratacao", options: { contratacaoFiltro: "pre-admissao" } };
    }
    if (filtro === "encerrados" || tab === "encerrados") {
      return { page: "contratacao", options: { contratacaoFiltro: "encerrados" } };
    }
    return { page: "resultados", options: {} };
  }
  if (hub === "relatorios" || hub === "painel" || hub === "indicadores") {
    return { page: "painel", options: { selecaoTab: "relatorio" } };
  }

  const legacy = pageByHash[raw] || pageByHash[hub];
  if (legacy) {
    if (legacy === "gestor") {
      return { page: "gestor", options: { gestorHomeFilter: gestorHomeFilterFromHash(raw || hub) } };
    }
    return { page: legacy, options: {} };
  }
  return { page: "dashboard", options: {} };
}

function gestorHomeFilterFromHash(hash) {
  const key = String(hash || "").replace(/^#/, "");
  if (key === "gestor-pendencias" || key === "analises-gestores") return "analises";
  if (key === "gestor-solicitacoes") return "solicitacoes";
  if (key === "gestor-vagas") return "vagas";
  if (key === "gestor-entrevistas" || key === "entrevistas") return "entrevistas";
  return "overview";
}

function gestorHashFromState() {
  if (gestorViewState.mode === "job") return "gestor-vagas";
  if (gestorViewState.homeFilter === "entrevistas") return "gestor-entrevistas";
  if (gestorViewState.homeFilter === "analises") return "gestor-pendencias";
  if (
    gestorViewState.homeFilter === "solicitacoes" ||
    (gestorViewState.homeFilter === "vagas" && gestorViewState.vagasHubTab === "solicitacoes")
  ) {
    return "gestor-solicitacoes";
  }
  if (gestorViewState.homeFilter === "vagas" || gestorViewState.homeFilter === "abertas") {
    return "gestor-vagas";
  }
  return "gestor";
}

function gestorNavKeyFromState() {
  if (gestorViewState.homeFilter === "entrevistas") return "entrevistas";
  if (gestorViewState.mode === "job") return "recrutamento";
  if (
    gestorViewState.homeFilter === "analises" ||
    gestorViewState.homeFilter === "vagas" ||
    gestorViewState.homeFilter === "abertas" ||
    gestorViewState.homeFilter === "solicitacoes" ||
    gestorViewState.homeFilter === "candidatos"
  ) {
    return "recrutamento";
  }
  return "inicio";
}

function gestorNavKeyFromDataset(nav) {
  if (nav === "pendencias" || nav === "recrutamento") {
    gestorViewState.vagasHubTab = "pendencias";
    return "analises";
  }
  if (nav === "entrevistas") return "entrevistas";
  if (nav === "solicitacoes") {
    gestorViewState.vagasHubTab = "solicitacoes";
    return "solicitacoes";
  }
  if (nav === "vagas") {
    gestorViewState.vagasHubTab = "vagas";
    return "vagas";
  }
  if (nav === "inicio") return "overview";
  return "overview";
}

function syncGestorNavCounts() {
  const counts = countGestorPendencies();
  const pendEl = document.querySelector("#gestorPendenciasNavCount");
  const vagasEl = document.querySelector("#gestorVagasNavCount");
  const solEl = document.querySelector("#gestorSolicitacoesNavCount");
  const hubPendEl = document.querySelector("#gestorHubPendenciasCount");
  const hubSolEl = document.querySelector("#gestorHubSolicitacoesCount");
  const ivEl = document.querySelector("#interviewsNavCountGestor");
  if (pendEl) pendEl.textContent = String(counts.total);
  if (vagasEl) vagasEl.textContent = String(myGestorJobs().length);
  const openStatuses = new Set([
    "Rascunho",
    "Enviada",
    "Em análise",
    "Aguardando aprovação",
    "Ajuste solicitado",
  ]);
  const solicitacoesN =
    myGestorHiringRequests().filter((item) => openStatuses.has(item.status)).length +
    myGestorApprovalRequests().length;
  if (solEl) solEl.textContent = String(solicitacoesN);
  if (hubPendEl) {
    hubPendEl.textContent = String(counts.total);
    hubPendEl.hidden = counts.total <= 0;
  }
  if (hubSolEl) {
    hubSolEl.textContent = String(solicitacoesN);
    hubSolEl.hidden = solicitacoesN <= 0;
  }
  if (ivEl) ivEl.textContent = String(myGestorInterviews().length);
}

function syncGestorSidebarChrome() {
  if (workspaceRole !== "gestor") return;
  if (currentAppPage !== "gestor" && currentAppPage !== "entrevistas" && currentAppPage !== "settings") return;
  const gestorNavKey =
    currentAppPage === "entrevistas"
      ? "entrevistas"
      : currentAppPage === "settings"
        ? "configuracoes"
        : gestorNavKeyFromState();
  document.querySelectorAll("[data-page]").forEach((item) => {
    if (!item.dataset.gestorNav) return;
    const active = item.dataset.gestorNav === gestorNavKey;
    item.classList.toggle("active", active);
    item.toggleAttribute("aria-current", active);
  });
  if (currentAppPage === "settings") {
    history.replaceState(null, "", "#configuracoes");
    return;
  }
  const hash =
    currentAppPage === "entrevistas" ? "gestor-entrevistas" : gestorHashFromState();
  history.replaceState(null, "", `#${hash}`);
}

