function goToPage(page, options = {}) {
  closeOverlayDialogs();
  if (entityDialog.open) entityDialog.close();
  if (interviewDetailDialog.open) interviewDetailDialog.close();
  if (candidateDialog.open && page !== "pipeline" && !(page === "jobs" && options.jobBoard)) {
    candidateDialog.close();
  }
  if (
    page === "resultados" &&
    (options.resultadosHubTab === "preadmissao" ||
      options.resultadosHubTab === "encerrados" ||
      ["contratados", "dispensados", "ocultados"].includes(options.resultTab))
  ) {
    page = "contratacao";
    options = {
      ...options,
      contratacaoFiltro:
        options.resultTab ||
        (options.resultadosHubTab === "encerrados" ? "encerrados" : "pre-admissao"),
    };
  }
  if (page === "jobs" && options.jobBoard && options.jobTitle) {
    jobBoardTitle = options.jobTitle;
    jobBoardView = options.jobView || jobBoardView || "kanban";
  } else if (page === "jobs" || page === "pipeline") {
    jobBoardTitle = "";
    jobBoardView = "kanban";
  } else {
    jobBoardTitle = "";
  }
  if (options.jobTitle) {
    renderJobFilter();
    jobFilter.value = options.jobTitle;
  } else if (!jobBoardTitle && page === "pipeline") {
    jobFilter.value = "all";
  }
  if (options.resultTab) selectResultTab(options.resultTab);
  if (options.talentTab) selectTalentTab(options.talentTab);
  if (options.talentId) selectedTalentId = options.talentId;
  if (options.interviewId) {
    selectedInterviewId = options.interviewId;
    const interview = interviews.find((item) => item.id === options.interviewId);
    if (interview) selectedInterviewDay = dayKey(interview.at);
  }
  showPage(page, options);
  if (page === "settings") setSettingsView(options.settingsView || "home");
  if (options.screeningTab) {
    screeningTab = options.screeningTab;
    renderScreenings();
  }
  if (options.candidateId) openCandidate(options.candidateId);
}

function handleGoTarget(target) {
  if (target.dataset.openTest) {
    if (candidateDialog.open) candidateDialog.close();
    goToPage("tecnicos", { testId: Number(target.dataset.openTest) });
    return;
  }
  if (target.dataset.openJob) {
    goToPage("jobs", { jobTitle: target.dataset.openJob, jobBoard: true });
    return;
  }
  if (target.dataset.openCandidate) {
    goToPage("pipeline", { candidateId: Number(target.dataset.openCandidate) });
    return;
  }
  if (target.dataset.goPage) {
    const page = target.dataset.goPage;
    if (page === "contratacao") {
      goToPage("contratacao", {
        contratacaoFiltro: target.dataset.contratacaoFiltro || "pre-admissao",
      });
      return;
    }
    if (page === "recrutamento") {
      goToPage("recrutamento", {
        recrutamentoTab: target.dataset.recrutamentoTab || "pipeline",
      });
      return;
    }
    if (page === "selecao") {
      const tab = target.dataset.selecaoTab || "instrumentos";
      if (tab === "entrevistas") {
        goToPage("entrevistas", { selecaoTab: "entrevistas" });
      } else if (tab === "resultados") {
        goToPage("resultados", { selecaoTab: "resultados" });
      } else if (tab === "relatorio") {
        goToPage("painel", { selecaoTab: "relatorio" });
      } else {
        goToPage("selecao", { selecaoTab: "instrumentos" });
      }
      return;
    }
    goToPage(page, {
      resultTab: target.dataset.resultTab,
      talentTab: target.dataset.talentTab,
      interviewId: target.dataset.interviewId
        ? Number(target.dataset.interviewId)
        : undefined,
    });
  }
}

document.querySelectorAll("[data-page]").forEach((link) => {
  link.addEventListener("click", (event) => {
    event.preventDefault();
    const page = ["indicadores", "relatorios"].includes(link.dataset.page)
      ? "painel"
      : link.dataset.page === "analisesGestores"
        ? "analisesGestores"
        : link.dataset.page;
    if (page === "gestor" && link.dataset.gestorNav) {
      const filter = gestorNavKeyFromDataset(link.dataset.gestorNav);
      if (filter === "entrevistas") {
        gestorViewState.homeFilter = "entrevistas";
        goToPage("entrevistas");
        return;
      }
      goToPage("gestor", { gestorHomeFilter: filter });
      return;
    }
    if (page === "entrevistas" && workspaceRole === "gestor") {
      gestorViewState.homeFilter = "entrevistas";
      goToPage("entrevistas");
      return;
    }
    if (page === "recrutamento") {
      goToPage("recrutamento", { recrutamentoTab: recrutamentoTab || "pipeline" });
      return;
    }
    if (page === "selecao") {
      const entry = link.dataset.selecaoEntry || "entrevistas";
      if (entry === "entrevistas") goToPage("entrevistas", { selecaoTab: "entrevistas" });
      else if (entry === "resultados") goToPage("resultados", { selecaoTab: "resultados" });
      else goToPage("selecao", { selecaoTab: "instrumentos" });
      return;
    }
    if (page === "contratacao") {
      goToPage("contratacao", { contratacaoFiltro: contratacaoFiltro || "pre-admissao" });
      return;
    }
    if (page === "painel") {
      goToPage("dashboard");
      return;
    }
    goToPage(page);
  });
});

