function resetCandidateMoreMenuPlacement(menu) {
  if (!menu) return;
  menu.style.position = "";
  menu.style.top = "";
  menu.style.right = "";
  menu.style.left = "";
  menu.style.bottom = "";
  menu.style.zIndex = "";
  menu.style.maxHeight = "";
  menu.style.overflow = "";
  menu.style.overflowY = "";
  const home = menu._candidateMoreHome;
  if (home && menu.parentElement !== home) {
    home.appendChild(menu);
  }
}

function resolveMoreMenuPlacement(trigger, options = {}) {
  const rect = trigger.getBoundingClientRect();
  const host =
    trigger.closest("dialog, .stack-dialog, .interview-detail-sheet, .assignment-detail-sheet") ||
    document.documentElement;
  const hostRect =
    typeof host.getBoundingClientRect === "function"
      ? host.getBoundingClientRect()
      : { left: 0, top: 0, width: window.innerWidth, height: window.innerHeight };
  const hostMidX = hostRect.left + hostRect.width / 2;
  const hostMidY = hostRect.top + hostRect.height / 2;
  const triggerMidX = rect.left + rect.width / 2;
  const triggerMidY = rect.top + rect.height / 2;

  let horizontal =
    options.align === "start" || options.align === "end"
      ? options.align
      : triggerMidX < hostMidX
        ? "start"
        : "end";
  let vertical =
    options.vertical === "up" || options.vertical === "down"
      ? options.vertical
      : triggerMidY < hostMidY
        ? "down"
        : "up";

  return { horizontal, vertical };
}

function placeCandidateMoreMenu(menu, trigger, options = {}) {
  if (!menu || !trigger) return;
  if (!menu._candidateMoreHome) {
    menu._candidateMoreHome = menu.parentElement;
  }
  // Mantém o menu dentro do <dialog> (top layer). Ir para document.body
  // deixa o dropdown atrás do modal e parece que o botão "não funciona".
  const home = menu._candidateMoreHome;
  if (home && menu.parentElement !== home) {
    home.appendChild(menu);
  }
  const rect = trigger.getBoundingClientRect();
  const gap = 6;
  const viewportPad = 12;
  const placement = resolveMoreMenuPlacement(trigger, options);
  let alignStart = placement.horizontal === "start";
  let openUp = placement.vertical === "up";

  menu.style.position = "fixed";
  menu.style.zIndex = "80";
  menu.style.maxHeight = "none";
  menu.style.overflow = "visible";
  menu.style.overflowY = "";

  if (alignStart) {
    menu.style.right = "auto";
    menu.style.left = `${Math.max(viewportPad, rect.left)}px`;
  } else {
    menu.style.left = "auto";
    menu.style.right = `${Math.max(viewportPad, window.innerWidth - rect.right)}px`;
  }

  if (openUp) {
    menu.style.top = "auto";
    menu.style.bottom = `${Math.max(viewportPad, window.innerHeight - rect.top + gap)}px`;
  } else {
    menu.style.bottom = "auto";
    menu.style.top = `${rect.bottom + gap}px`;
  }

  let menuRect = menu.getBoundingClientRect();
  if (alignStart && menuRect.right > window.innerWidth - viewportPad) {
    menu.style.left = "auto";
    menu.style.right = `${viewportPad}px`;
    alignStart = false;
  } else if (!alignStart && menuRect.left < viewportPad) {
    menu.style.right = "auto";
    menu.style.left = `${viewportPad}px`;
    alignStart = true;
  }

  menuRect = menu.getBoundingClientRect();
  const spaceBelow = window.innerHeight - rect.bottom - viewportPad;
  const spaceAbove = rect.top - viewportPad;
  const menuHeight = menuRect.height;

  if (openUp) {
    if (menuHeight > spaceAbove && spaceBelow > spaceAbove) {
      openUp = false;
      menu.style.bottom = "auto";
      menu.style.top = `${rect.bottom + gap}px`;
    } else if (menuHeight > spaceAbove) {
      menu.style.maxHeight = `${Math.max(160, spaceAbove)}px`;
      menu.style.overflowY = "auto";
    }
  } else if (menuHeight > spaceBelow && spaceAbove > spaceBelow) {
    openUp = true;
    menu.style.top = "auto";
    menu.style.bottom = `${window.innerHeight - rect.top + gap}px`;
    if (menuHeight > spaceAbove) {
      menu.style.maxHeight = `${Math.max(160, spaceAbove)}px`;
      menu.style.overflowY = "auto";
    }
  } else if (menuHeight > spaceBelow) {
    menu.style.maxHeight = `${Math.max(160, spaceBelow)}px`;
    menu.style.overflowY = "auto";
  }
}

function closeCandidateMoreActions() {
  const menu = document.querySelector("#candidateMoreActionsMenu");
  const trigger = document.querySelector("#candidateMoreActionsBtn");
  if (!menu || !trigger) return;
  menu.hidden = true;
  trigger.setAttribute("aria-expanded", "false");
  resetCandidateMoreMenuPlacement(menu);
}

function toggleCandidateMoreActions() {
  const menu = document.querySelector("#candidateMoreActionsMenu");
  const trigger = document.querySelector("#candidateMoreActionsBtn");
  if (!menu || !trigger) return;
  const opening = menu.hidden;
  if (!opening) {
    closeCandidateMoreActions();
    return;
  }
  menu.hidden = false;
  trigger.setAttribute("aria-expanded", "true");
  placeCandidateMoreMenu(menu, trigger);
}

function setCandidateActivityCollapsed(collapsed) {
  const body = document.querySelector("#candidateModalBody");
  const panel = document.querySelector("#activityPanel");
  const reveal = document.querySelector("#showActivities");
  if (!body || !panel || !reveal) return;
  if (body.querySelector(".candidate-dossier-groups")) {
    reveal.hidden = true;
    panel.hidden = selectedCandidateDossierTab !== "comments";
    return;
  }
  body.classList.toggle("is-activity-collapsed", collapsed);
  panel.hidden = collapsed;
  reveal.hidden = !collapsed;
  if (activityList) activityList.hidden = false;
}

on("#candidateDialog", "click", (event) => {
  const group = event.target.closest("[data-dossier-group]");
  if (group) {
    setCandidateDossierGroup(group.dataset.dossierGroup);
    return;
  }
  const tab = event.target.closest("[data-candidate-tab]");
  if (tab) {
    setCandidateDossierTab(tab.dataset.candidateTab);
    return;
  }
  const nextTabBtn = event.target.closest("[data-dossier-next-tab]");
  if (nextTabBtn) {
    const tabName = nextTabBtn.dataset.dossierNextTab;
    const focus = nextTabBtn.dataset.dossierFocus;
    if (tabName === "comments") setCandidateDossierGroup("comments");
    else if (tabName === "evaluation") setCandidateDossierGroup("eval");
    else if (tabName === "history") setCandidateDossierGroup("history");
    else setCandidateDossierTab(tabName);
    if (focus) {
      window.setTimeout(() => focusPendingTarget(focus, { focus: false }), 40);
    }
    return;
  }
  const metricBtn = event.target.closest("[data-dossier-metric]");
  if (metricBtn) {
    const kind = metricBtn.dataset.dossierMetric;
    setCandidateDossierGroup("eval");
    window.setTimeout(() => {
      focusPendingTarget(
        kind === "fit" ? "#candidateSectionFit" : "#candidateSectionScore",
        { focus: false },
      );
    }, 40);
    return;
  }
  const candidate = candidates.find((item) => item.id === selectedCandidateId);
  if (!candidate) return;

  if (event.target.closest("#toggleArchivedComments")) {
    showArchivedCandidateComments = !showArchivedCandidateComments;
    renderCandidateDetails(candidate);
    return;
  }

  const openInterviewBtn = event.target.closest("[data-open-interview]");
  if (openInterviewBtn) {
    const interview = interviews.find(
      (item) => String(item.id) === openInterviewBtn.dataset.openInterview,
    );
    if (interview) openInterviewDetail(interview);
    return;
  }

  const replaceDocBtn = event.target.closest("[data-replace-doc]");
  if (replaceDocBtn) {
    pendingReplaceDocId = replaceDocBtn.dataset.replaceDoc;
    document.querySelector("#candidateDocumentInput")?.click();
    return;
  }

  const viewDocBtn = event.target.closest("[data-view-doc]");
  if (viewDocBtn) {
    const doc = ensureCandidateDocuments(candidate).find(
      (item) => item.id === viewDocBtn.dataset.viewDoc,
    );
    if (!doc) return;
    showToast(
      doc.name,
      doc.fileName
        ? `Pré-visualização stub de ${doc.fileName}.`
        : "Nenhum arquivo anexado.",
    );
    return;
  }

  const approveDocBtn = event.target.closest("[data-doc-approve]");
  if (approveDocBtn) {
    const doc = ensureCandidateDocuments(candidate).find(
      (item) => item.id === approveDocBtn.dataset.docApprove,
    );
    if (!doc) return;
    doc.status = "Aprovado";
    doc.rejectReason = "";
    doc.updatedAt = "agora";
    const pre = findPreAdmissionForCandidate(candidate.id);
    if (pre) {
      const mirror = pre.checklist.find((item) => item.id === doc.id);
      if (mirror) {
        mirror.status = "Aprovado";
        mirror.fileName = mirror.fileName || doc.fileName;
      }
    }
    candidate.history.unshift([
      "Documento",
      `${doc.name}: Aprovado · Larissa Dias · agora`,
    ]);
    renderCandidateDetails(candidate);
    showToast("Documento aprovado", doc.name);
    return;
  }

  const rejectDocBtn = event.target.closest("[data-doc-reject]");
  if (rejectDocBtn) {
    const doc = ensureCandidateDocuments(candidate).find(
      (item) => item.id === rejectDocBtn.dataset.docReject,
    );
    if (!doc) return;
    const reason = window.prompt("Motivo da rejeição:", doc.rejectReason || "");
    if (reason == null) return;
    if (!reason.trim()) {
      showToast("Motivo obrigatório", "Informe o motivo da rejeição.");
      return;
    }
    doc.status = "Rejeitado";
    doc.rejectReason = reason.trim();
    doc.updatedAt = "agora";
    const pre = findPreAdmissionForCandidate(candidate.id);
    if (pre) {
      const mirror = pre.checklist.find((item) => item.id === doc.id);
      if (mirror) mirror.status = "Rejeitado";
    }
    candidate.history.unshift([
      "Documento",
      `${doc.name}: Rejeitado — ${doc.rejectReason} · Larissa Dias · agora`,
    ]);
    renderCandidateDetails(candidate);
    showToast("Documento rejeitado", doc.name);
    return;
  }

  const editButton = event.target.closest("[data-edit-comment]");
  const archiveButton = event.target.closest("[data-archive-comment]");
  if (editButton) {
    const comment = ensureCandidateComments(candidate).find(
      (item) => String(item.id) === editButton.dataset.editComment,
    );
    if (!comment || comment.archived) return;
    const nextMessage = window.prompt("Editar comentário:", comment.message);
    if (!nextMessage?.trim()) return;
    comment.message = nextMessage.trim();
    comment.time = "Editado agora";
    candidate.history.unshift(["Comentário editado", `${comment.message} · Larissa Dias`]);
    renderCandidateDetails(candidate);
    return;
  }
  if (archiveButton) {
    const comment = ensureCandidateComments(candidate).find(
      (item) => String(item.id) === archiveButton.dataset.archiveComment,
    );
    if (!comment) return;
    comment.archived = !comment.archived;
    candidate.history.unshift([
      comment.archived ? "Comentário arquivado" : "Comentário restaurado",
      `${comment.message} · Larissa Dias`,
    ]);
    renderCandidateDetails(candidate);
  }
});

on("#candidateReplaceResume", "click", () => {
  document.querySelector("#candidateReplaceResumeInput")?.click();
});

on("#candidateReplaceResumeInput", "change", (event) => {
  const candidate = candidates.find((item) => item.id === selectedCandidateId);
  const file = event.target.files?.[0];
  if (!candidate || !file) return;
  if (candidate.attachment && candidate.resumeFileName) {
    if (
      !window.confirm(
        `Substituir o currículo atual (${candidate.resumeFileName})? A versão anterior ficará no histórico.`,
      )
    ) {
      event.target.value = "";
      return;
    }
    candidate.history.unshift([
      "Currículo anterior",
      `${candidate.resumeFileName} · arquivado · agora`,
    ]);
  }
  candidate.attachment = true;
  candidate.resumeFileName = file.name;
  candidate.history.unshift(["Currículo atualizado", `${file.name} · agora`]);
  renderCandidateDetails(candidate);
  setCandidateDossierTab("resume");
  renderPipeline();
  event.target.value = "";
  showToast("Currículo atualizado", file.name);
});

on("#candidateAddDocument", "click", () => {
  pendingReplaceDocId = null;
  document.querySelector("#candidateDocumentInput")?.click();
});

on("#candidateDocumentInput", "change", (event) => {
  const candidate = candidates.find((item) => item.id === selectedCandidateId);
  const file = event.target.files?.[0];
  if (!candidate || !file) return;
  const checklist = ensureCandidateDocuments(candidate);
  if (pendingReplaceDocId) {
    const doc = checklist.find((item) => item.id === pendingReplaceDocId);
    pendingReplaceDocId = null;
    if (!doc) {
      event.target.value = "";
      return;
    }
    if (doc.fileName) {
      if (
        !window.confirm(
          `Substituir ${doc.name} (${doc.fileName})? A versão anterior ficará no histórico.`,
        )
      ) {
        event.target.value = "";
        return;
      }
      candidate.history.unshift([
        "Documento anterior",
        `${doc.name}: ${doc.fileName} · arquivado · agora`,
      ]);
    }
    doc.fileName = file.name;
    doc.status = "Enviado";
    doc.rejectReason = "";
    doc.updatedAt = "agora";
    candidate.history.unshift(["Documento enviado", `${doc.name}: ${file.name} · agora`]);
  } else {
    candidate.documents = [...(candidate.documents || []), file.name];
    const pendingDoc = checklist.find((item) => item.status === "Pendente") || checklist[0];
    if (pendingDoc) {
      pendingDoc.fileName = file.name;
      pendingDoc.status = "Enviado";
      pendingDoc.rejectReason = "";
      pendingDoc.updatedAt = "agora";
    }
    candidate.history.unshift(["Documento adicionado", `${file.name} · agora`]);
  }
  renderCandidateDetails(candidate);
  setCandidateDossierTab("documents");
  event.target.value = "";
  showToast("Documento atualizado", file.name);
});

